    entries1: Object.entries(Enum1),
    keys1: Object.keys(Enum1),
    values1: Object.values(Enum1),
  },
  Enum2: {
    entries2: Object.entries(Enum2), // <--- WRONG (extra entries) only while REPL
    keys2: Object.keys(Enum2), // <--- WRONG (extra keys) only while REPL
