What steps can reproduce the bug?
A decorated class whose body contains a static {} block that writes a symbol
onto the class. The decorator reads that symbol. Bun's decorator lowering
extracts the static block out of the class body and runs it after the
decorator application, so the decorator observes the class before the
registration happened and sees nothing.
Standalone repro (no dependencies):
// repro.mjs
const REG = Symbol.for("schema");

let decoratorSyms = [];
let captured;

function registerSchema(target) {
  target[REG] = { type: "object" }; // stand-in for a schema-registration helper
}

function Server() {
  return function (target) {
    decoratorSyms = Object.getOwnPropertySymbols(target).map(String);
    captured = target[REG]; // stand-in for a reflection lookup
    return target;
  };
}

@Server()
class DemoService {
  propStr = "test";
  static {
    registerSchema(DemoService);
  }
}
void DemoService;

console.log("decorator-time syms:", JSON.stringify(decoratorSyms));
console.log("captured:", captured ? "yes" : "UNDEFINED");
console.log(captured ? "WORKS" : "BROKEN");
Run with:
bun repro.mjs
# decorator-time syms: []
# captured: UNDEFINED
# BROKEN
What is the expected behavior?
The static block runs as part of class evaluation, before the decorator
application, so the decorator sees the registration already present:
let DemoService = class DemoService {
  static {
    registerSchema(DemoService);   // inside the class body, before __decorate
  }
};
DemoService = __decorate([Server()], DemoService);
Expected output:
decorator-time syms: ["Symbol(schema)"]
captured: yes
WORKS
What do you see instead?
Bun's lowering extracts the static block out of the class body and places the
registration after __decorateElement runs:
var _dec = [Server()];
var _init = __decoratorStart(undefined);

class DemoService {
  propStr = "test";
}
DemoService = __decorateElement(_init, 0, "DemoService", _dec, DemoService); // decorator FIRST
registerSchema(DemoService);                                                  // registration AFTER
__runInitializers(_init, 1, DemoService);
__decoratorMetadata(_init, DemoService);
So the decorator runs first, sees no symbol, and the lookup returns undefined:
decorator-time syms: []
captured: UNDEFINED
BROKEN
