Reproduction
This reproduction uses one package that exports one function, one local HTTP server, and one consumer that uses the isolated linker.
Create these files:
package/package.json
{
  "name": "tiny-query-package",
  "version": "1.0.0",
  "type": "module",
  "exports": "./index.js",
  "files": ["index.js"]
}
package/index.js
export const answer = () => 42;
server/server.mjs
import { createReadStream, statSync } from "node:fs";
import { createServer } from "node:http";
import { fileURLToPath } from "node:url";

const tarball = fileURLToPath(
  new URL("./tiny-query-package-1.0.0.tgz", import.meta.url),
);

createServer((request, response) => {
  if (new URL(request.url, "http://localhost").pathname !== "/pkg.tgz") {
    response.writeHead(404).end();
    return;
  }

  response.writeHead(200, {
    "content-length": statSync(tarball).size,
    "content-type": "application/octet-stream",
  });
  createReadStream(tarball).pipe(response);
}).listen(8123, "127.0.0.1", () => console.log("listening on 8123"));
consumer/package.json
{
  "name": "consumer",
  "private": true,
  "type": "module"
}
consumer/bunfig.toml
[install]
linker = "isolated"
consumer/index.mjs
import { answer } from "tiny-query-package";

console.log(answer());
