Node's documented contract for the lookup option on http.request() / https.request() is a callback shaped (err, address, family) — see the Node.js docs for dns.lookup(), which is the default lookup implementation these options replace. Bun 1.3.14 does not honor that scalar form. When a custom lookup calls back with (null, "127.0.0.1", 4), Bun's internal resolver plumbing throws TypeError: results.sort is not a function — it appears to assume the callback always receives the all: true array shape ([{ address, family }, ...]) regardless of what the caller requested or documented.
The array form works correctly. Only the documented scalar form is broken.
Minimal repro (plain node:http, no third-party dependencies):
// repro.js — run with: bun repro.js
const http = require("node:http");

// A trivial local server to receive the pinned connection.
const server = http.createServer((_req, res) => {
  res.writeHead(200);
  res.end("ok");
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;

  const req = http.request(
    {
      host: "example.invalid", // deliberately unresolvable — lookup must override it
      port,
      path: "/",
      // Documented Node contract: (err, address, family). This is the SCALAR
      // form, not the `all:true` array form.
      lookup: (_hostname, _options, cb) => {
        cb(null, "127.0.0.1", 4);
      },
    },
    (res) => {
      console.log("SUCCEEDED, status:", res.statusCode);
      res.resume();
      server.close();
    },
  );
  req.on("error", (err) => {
    console.log("ERRORED:", err);
    server.close();
  });
  req.end();
});
