(function () {
  const cb2 = new JSCallback(() => {}, { args: ["int32_t"], threadsafe: true });
  new CFunction({ ptr: cb2.ptr, returns: "void", args: ["int32_t"] })(1);
})();
await 1;
Bun.gc(true);

await new Promise(r => setTimeout(r, 20));
console.log(got); // {} or {value:"CFunction1"} instead of -64n
