  let energy: f64 = 0.0;
  for (let i = 0; i < iterations; i++) {
    // Bun parses this, sees it's wrapped in `compile()`, 
    // and translates the AST to pure Rust: 
    // e.g., `let mut energy: f64 = 0.0; for i in 0..iterations { ... }`
    energy += 0.5 * mass * (velocity * velocity);
  }
  return energy;
});

// 2. Execution has ZERO JavaScript engine overhead.
// It executes as a raw native CPU instruction block.
const result = computeHeavyPhysics(15.5, 299792458.0, 1_000_000);
