     * Allocates memory off-heap directly via Rust's underlying allocator.
     * Returns a raw pointer, completely bypassing JSC garbage collection.
     */
    function alloc(size: number): Pointer;

    /**
     * Frees previously allocated off-heap memory.
     * The developer is 100% responsible for preventing Use-After-Free crashes.
