import { mkdirSync, writeFileSync } from "fs";
import { mkdtempSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";

const tmp = mkdtempSync(join(tmpdir(), "bun-glob-"));
mkdirSync(join(tmp, "svc", "src"), { recursive: true });
writeFileSync(join(tmp, "svc", "src", "env.ts"), "");
writeFileSync(join(tmp, "svc", "env.ts"), "");

// Brace pattern with path separator inside braces — scan() returns []
const g1 = new Bun.Glob("svc/{src/env.ts,env.ts}");
const scan1 = [];
for await (const f of g1.scan({ cwd: tmp, dot: true })) scan1.push(f);
console.log("scan with path sep in braces:", scan1);
// => []  (WRONG — should find both files)

// match() works correctly for the same pattern
console.log("match svc/src/env.ts:", g1.match("svc/src/env.ts"));
// => true
console.log("match svc/env.ts:", g1.match("svc/env.ts"));
// => true

// Brace pattern WITHOUT path separator — scan() works correctly
const g2 = new Bun.Glob("svc/src/{env,index}.ts");
const scan2 = [];
for await (const f of g2.scan({ cwd: tmp, dot: true })) scan2.push(f);
console.log("scan without path sep in braces:", scan2);
// => ["svc\src\env.ts"]  (CORRECT)
What is the expected behavior?
scan() should return matching files for brace patterns containing path separators, consistent with how match() handles the same pattern.
Expected output:
scan with path sep in braces: [ "svc\src\env.ts", "svc\env.ts" ]
match svc/src/env.ts: true
match svc/env.ts: true
scan without path sep in braces: [ "svc\src\env.ts" ]

What do you see instead?
scan() silently returns an empty array for brace patterns with path separators inside the braces. No error is thrown.
Actual output:
scan with path sep in braces: []
match svc/src/env.ts: true
match svc/env.ts: true
scan without path sep in braces: [ "svc\src\env.ts" ]

Additional information
Root cause hypothesis: PR #16824 ("Glob Match Rewrite") rewrote matchImpl in src/glob/ascii.zig to recursively expand braces (1{foo,bar}2 → [1foo2, 1bar2]), which fixed brace expansion for match(). However, the scanner (GlobWalker.zig) appears to still use the old brace handling logic, which doesn't expand braces containing path separators during directory traversal.
