#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <unistd.h>

struct coord {
    pthread_mutex_t mutex;
    pthread_cond_t  cond;
    volatile int    busy;          // the "still-busy" predicate
};
static struct coord *C;

// Mimics a woken-but-slow waiter (a heavily contended scheduler delays it).
static void slow(void){ for (volatile int i = 0; i < 200; i++) {} }

static void *waiter(void *arg) {
    (void)arg;
    pthread_mutex_lock(&C->mutex);
    while (C->busy) {
        pthread_cond_wait(&C->cond, &C->mutex);   // woken by broadcast below
        slow();                                    // delayed leaving the wait

