  ws.onopen = async () => {
    const rss0 = process.memoryUsage().rss;
    for (let i = 0; i < 4000; i++) {
      ws.send(MSG); // 4000 * 64 KiB = 250 MiB
      if (ws.bufferedAmount > maxBuffered) maxBuffered = ws.bufferedAmount;
