const listAllShards = async (): Promise<Shard[]> => {
  const shards: Shard[] = []
  let nextToken: string | undefined
  do {
    const resp = await kinesis.send(
      new ListShardsCommand({
        StreamName: nextToken ? undefined : STREAM,
        NextToken: nextToken,
      }),
    )
    if (resp.Shards) shards.push(...resp.Shards)
    nextToken = resp.NextToken
  } while (nextToken)
  return shards
}

const pollShard = async (shardId: string) => {
  const { ShardIterator } = await kinesis.send(
    new GetShardIteratorCommand({
      StreamName: STREAM,
