    const resp = await kinesis.send(
      new GetRecordsCommand({ ShardIterator: iterator, Limit: 1000 }),
    )
    // Discard records — the leak is in the fetch path, not the consumer
    iterator = resp.NextShardIterator
    await sleep(POLL_MS)
  }
}

