There are some very niche cases where synchronously waiting for a promise is useful. It is, for example, used today in bun:test to make synchronous looking expect(...).resolved wait for an asynchronous promise. It is possible to exploit this today to generate a userland waitForPromise function:
import { expect } from 'bun:test';

export function waitForPromise<T>(promise: Promise<T>): T {
  let result: T = undefined as T;
  let err: unknown;
  expect(
    promise.then(
      (v) => {
        result = v;
        return true;
      },
      (e) => {
        err = e;
      },
    ),
  ).resolves.toEqual(expect.anything());
  if (err) {
    throw err;
  }
  return result;
}
Now:
const a = Promise.resolve().then(() => 5);
const val = waitForPromise(a);
// val === 5;
