import { createSocket, type Socket } from "node:dgram";

const HOST = "0.0.0.0";
const PORT = 56780;

function bindOnce(reusePort: boolean): Promise<{ ok: boolean; message: string; socket: Socket | null }> {
  return new Promise((resolve) => {
    const s = createSocket({ type: "udp4", reuseAddr: true, reusePort });
    let done = false;
    const finish = (x: { ok: boolean; message: string; socket: Socket | null }) => {
      if (done) return;
      done = true;
      resolve(x);
    };
    s.once("error", (e) => finish({ ok: false, message: `${e.name}: ${e.message}`, socket: null }));
    s.bind(PORT, HOST, () => finish({ ok: true, message: `bound ${HOST}:${PORT}`, socket: s }));
  });
}

