When an http.Server.listen() call fails with EADDRINUSE and you call .listen() again on the same server object with a different port, the second call never emits listening or error — it hangs forever.
This is the exact pattern Vite uses for port auto-increment (httpServerStart in packages/vite/src/node/http.ts), so this bug breaks vite dev when the default port is already in use.
Minimal reproduction:
const net = require("net");
const http = require("http");

async function test() {
  // Occupy port 4321
  const blocker = net.createServer();
  await new Promise((resolve) => blocker.listen(4321, "0.0.0.0", resolve));
  console.log("Port 4321 occupied");

  const httpServer = http.createServer((req, res) => res.end("ok"));

  let port = 4321;
  const result = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      console.log("HUNG after 5s at port " + port);
      resolve("timeout");
    }, 5000);

    const onError = (e) => {
      if (e.code === "EADDRINUSE") {
        console.log("EADDRINUSE on port " + port + ", retrying " + (port + 1));
        httpServer.listen(++port, "0.0.0.0");
      } else {
        clearTimeout(timeout);
        httpServer.removeListener("error", onError);
        reject(e);
      }
    };
    httpServer.on("error", onError);
    httpServer.listen(port, "0.0.0.0", () => {
      clearTimeout(timeout);
      httpServer.removeListener("error", onError);
      resolve("ok:" + port);
    });
  });
  console.log("Result: " + result);

  httpServer.close();
  blocker.close();
}

test().catch(console.error);
What is the expected behavior?
Node.js output (correct):
Port 4321 occupied
EADDRINUSE on port 4321, retrying 4322
Result: ok:4322

The second .listen(4322) call succeeds and emits listening.
What do you see instead?
Bun output:
Port 4321 occupied
EADDRINUSE on port 4321, retrying 4322
HUNG after 5s at port 4322
Result: timeout

The second .listen(4322) call never emits listening or error. The server hangs forever.
Additional information
This directly breaks Vite's dev server port auto-increment. When running vite dev (or astro dev) under Bun and the default port is occupied, Vite logs "Port X is in use, trying another one..." and then hangs indefinitely.
Related issues: #15560, #4906, #19790

