    t       = 0,
    x       = 96,
    y       = 24,
    animIdx = 0;

function saveState(): void {
  pmem(0, t);
  pmem(1, x);
  pmem(2, y);
  pmem(3, animIdx);
  trace("[INFO]: State saved!");
}

function loadState(): void {
  const lastBuildId = pmem(__PMEM_BUILD_ID);
  if (lastBuildId === __BUILD_ID) return;
  pmem(__PMEM_BUILD_ID, __BUILD_ID);
  trace("[INFO]: Checking for hot-reload...");
  t       = pmem(0);
  x       = pmem(1);
  y       = pmem(2);
  animIdx = pmem(3);
  trace("[INFO]: State loaded!");
}

