[install]
linker = "isolated"
package.json
{
  "workspaces": ["packages/*", "apps/*"]
}
packages/lib-react18/package.json
{
  "name": "lib-react18",
  "dependencies": {
    "@ariakit/react": "^0.4.20",
    "react": "^18.3.1"
  },
  "devDependencies": {
    "@types/react": "^18.3.27"
  }
}
apps/app-react19/package.json
{
  "name": "app-react19",
